</p>

<p>Sends a confirmation link to the new address and a notice to the
current one. The current email stays on the account until the new one
is confirmed. <code>current_password</code> is required unless the account was
created with Google and has no password.</p>

<span id="example-requests-POSTapi-v1-me-email">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request POST \
    "http://localhost:8000/api/v1/me/email" \
    --header "Authorization: Bearer {YOUR_AUTH_KEY}" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"email\": \"gbailey@example.net\"
}"
</code></pre></div>


