                <h1 id="auth">Auth</h1>

    

                                <h2 id="auth-POSTapi-v1-auth-register">Sign up</h2>

<p>
</p>

<p>Creates a boarder account (every new account starts as a boarder; owner
and caretaker roles are added later), records privacy consent and sends
the confirmation email. No token is returned: the email must be
confirmed before the first login.</p>

<span id="example-requests-POSTapi-v1-auth-register">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request POST \
    "http://localhost:8000/api/v1/auth/register" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"name\": \"b\",
    \"email\": \"zbailey@example.net\",
    \"phone\": \"-666-09\",
    \"password\": \"architecto\",
    \"consent\": true,
    \"device_name\": \"n\"
}"
</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost:8000/api/v1/auth/register"
);

const headers = {
    "Content-Type": "application/json",
    "Accept": "application/json",
};

let body = {
    "name": "b",
    "email": "zbailey@example.net",
    "phone": "-666-09",
    "password": "architecto",
    "consent": true,
    "device_name": "n"
};

fetch(url, {
    method: "POST",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre></div>

</span>

