                <h1 id="dorm-finder">Dorm Finder</h1>

    

                                <h2 id="dorm-finder-GETapi-v1-listings">Search listings</h2>

<p>
</p>

<p>Published properties of verified owners with at least one free unit.
Prices in centavos. <code>bbox</code> = south,west,north,east (map view).</p>

<span id="example-requests-GETapi-v1-listings">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request GET \
    --get "http://localhost:8000/api/v1/listings" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"q\": \"b\",
    \"min_price\": 39,
    \"max_price\": 84,
    \"rental_mode\": \"bedspaces\",
    \"who\": \"z\",
    \"bbox\": \"1,42.3268)))\",
    \"page\": 73
}"
</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost:8000/api/v1/listings"
);

const headers = {
    "Content-Type": "application/json",
    "Accept": "application/json",
};

let body = {
    "q": "b",
    "min_price": 39,
    "max_price": 84,
    "rental_mode": "bedspaces",
    "who": "z",
    "bbox": "1,42.3268)))",
    "page": 73
};

fetch(url, {
    method: "GET",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre></div>

