                    <h2 id="owner-PUTapi-v1-owner-profile">Update business name and payment instructions</h2>

<p>
<small class="badge badge-darkred">requires authentication</small>
</p>

<p>The GCash and bank details boarders see when they pay. Only the owner
can change them (never a caretaker).</p>

<span id="example-requests-PUTapi-v1-owner-profile">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request PUT \
    "http://localhost:8000/api/v1/owner/profile" \
    --header "Authorization: Bearer {YOUR_AUTH_KEY}" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"business_name\": \"b\",
    \"gcash_name\": \"n\",
    \"gcash_number\": \"9360-923-2\",
    \"bank_name\": \"w\",
    \"bank_account_name\": \"p\",
    \"bank_account_number\": \"w\"
}"
</code></pre></div>


<div class="javascript-example">
