                    <h2 id="units-PATCHapi-v1-units--unit_id--not-ready">Mark a unit (not) ready</h2>

<p>
<small class="badge badge-darkred">requires authentication</small>
</p>

<p>Needs cleaning or repairs: hidden from bookings until cleared (S1). Does
not change anyone's tenancy.</p>

